s = input()
n = len(s)
if n == 1 or n == 2:
	print(s)
else:
	a = ['a', 'e', 'i', 'o', 'u']
	(q, w) = ('', '')
	if s[0] not in a:
		q = s[0]
	if s[1] not in a:
		w = s[1]
	res = s[:2]
	for i in range(2, n):
		e = s[i]
		if e not in a:
			if q != '' and w != '':
				if q == w == e:
					q = w
					res += e
				else:
					res += ' ' + e
					(q, w) = ('', e)
			else:
				(q, w) = (w, e)
				res += e
		else:
			res += e
			(q, w) = ('', '')
	print(res)
